class HomeScreen extends ConsumerWidget{const HomeScreen({super.key,required this.onNavigate});final ValueChanged<int> onNavigate;
@override Widget build(BuildContext context,WidgetRef ref){ref.listen(billsProvider,(previous,next){if(next.hasValue)ReminderService.refreshFromCloud();});final bills=ref.watch(hydratedBillsProvider);final open=bills.where((b)=>b['status']!='closed').toList();final due=open.fold<double>(0,(v,b)=>v+(b['total_due'] as num).toDouble());final paid=open.fold<double>(0,(v,b)=>v+(b['total_paid'] as num).toDouble());final pending=open.fold<double>(0,(v,b)=>v+(b['pending'] as num).toDouble());return Scaffold(appBar:AppBar(title:Row(children:[ClipRRect(borderRadius:BorderRadius.circular(9),child:Image.asset('assets/sa-traders-logo.jpg',height:36,width:36,fit:BoxFit.cover)),const SizedBox(width:10),const Text('S.A Traders',style:TextStyle(fontWeight:FontWeight.w800))]),actions:[IconButton(tooltip:'Notifications',onPressed:()=>onNavigate(2),icon:const Icon(Icons.notifications_outlined))]),body:RefreshIndicator(onRefresh:()async{await ref.refresh(billsProvider.future);},child:ListView(padding:const EdgeInsets.fromLTRB(18,6,18,90),children:[Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(color:AppColors.teal,borderRadius:BorderRadius.circular(26)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('RENTAL OVERVIEW',style:Theme.of(context).textTheme.labelMedium?.copyWith(color:Colors.white70,letterSpacing:1.2,fontWeight:FontWeight.w700)),const SizedBox(height:14),Text(moneyLabel(pending),style:Theme.of(context).textTheme.headlineMedium?.copyWith(color:Colors.white,fontWeight:FontWeight.w900)),const SizedBox(height:4),const Text('Pending across active bills',style:TextStyle(color:Colors.white70)),const SizedBox(height:20),Row(children:[_heroMetric('Active bills','${open.length}'),const SizedBox(width:28),_heroMetric('Collected',moneyLabel(paid))])])),const SizedBox(height:14),GridView.count(crossAxisCount:2,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisSpacing:12,mainAxisSpacing:12,childAspectRatio:1.55,children:[StatCard(label:'Total due',value:moneyLabel(due),icon:Icons.account_balance_wallet_outlined),StatCard(label:'Collected',value:moneyLabel(paid),icon:Icons.check_circle_outline,color:AppColors.green)]),SectionTitle('Recent active bills',trailing:TextButton(onPressed:()=>onNavigate(1),child:const Text('See all'))),if(open.isEmpty)const EmptyState(title:'No active bills yet',description:'Create a rental bill to start tracking cycles and payments.')else ...open.take(6).map((b)=>Padding(padding:const EdgeInsets.only(bottom:10),child:_BillTile(bill:b,onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>BillDetailScreen(billNo:'${b['bill_no']}'))))))])));}
