class _BillTile extends StatelessWidget{const _BillTile({required this.bill,required this.onTap});final Map<String,dynamic> bill;final VoidCallback onTap;@override Widget build(BuildContext context)=>Card(child:ListTile(onTap:onTap,contentPadding:const EdgeInsets.symmetric(horizontal:16,vertical:7),leading:CircleAvatar(backgroundColor:AppColors.paleBlue.withValues(alpha:.3),child:Text('${bill['name']??'S'}'.trim().isEmpty?'S':'${bill['name']}'.trim()[0].toUpperCase(),style:const TextStyle(color:AppColors.teal,fontWeight:FontWeight.w800))),title:Text('${bill['name']??'Customer'}',style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text('Bill #${bill['bill_no']} · ${bill['mobile']??''}'),trailing:Column(mainAxisAlignment:MainAxisAlignment.center,crossAxisAlignment:CrossAxisAlignment.end,children:[Text(moneyLabel(bill['pending']??0),style:const TextStyle(fontWeight:FontWeight.w800,color:AppColors.red)),const Text('PENDING',style:TextStyle(fontSize:9,color:AppColors.gray,letterSpacing:1))])));}
